1	#include "rbtree.h"
2	
3	#include <assert.h>
4	#include <stddef.h>
5	#include <stdio.h>
6	#include <stdlib.h>
7	#include <string.h>
8	
9	/* White-box access to rbnode_t / struct rbtree for the invalid-tree fixtures
10	 * in test_rb_validate below -- rbtree_t stays opaque in rbtree.h by design,
11	 * but rb_validate's negative cases can't be built through the public API
12	 * (rb_insert should never itself produce an invalid tree). See Makefile:
13	 * $(SRC) is deliberately not compiled into $(BIN) separately, to avoid
14	 * double-defining the symbols this pulls in. */
15	#include "../src/rbtree.c"
16	
17	/* Provided by tests/fault_malloc.c: forces a specific rb_malloc call inside
18	 * rb_create to return NULL, without touching libc malloc. */
19	extern void fault_malloc_arm(int nth_call_to_fail);
20	extern void fault_malloc_disarm(void);
21	extern int fault_malloc_free_count(void);
22	
23	static int value_free_calls = 0;
24	
25	static void counting_free(void *value)
26	{
27	    (void)value;
28	    value_free_calls++;
29	}
30	
31	static void count_cb(const char *key, void *value, void *ctx)
32	{
33	    (void)key;
34	    (void)value;
35	    (*(int *)ctx)++;
36	}
37	
38	/* Tracks which value pointers the tree has actually freed, so insert tests
39	 * can tell "old value freed on overwrite" apart from "value untouched on
40	 * allocation failure" instead of just trusting the return code. */
41	#define MAX_FREED 16
42	static void *freed_values[MAX_FREED];
43	static int freed_count;
44	
45	static void reset_tracking(void)
46	{
47	    freed_count = 0;
48	}
49	
50	static void track_free(void *value)
51	{
52	    assert(freed_count < MAX_FREED);
53	    freed_values[freed_count++] = value;
54	    free(value);
55	}
56	
57	static int was_freed(void *value)
58	{
59	    for (int i = 0; i < freed_count; i++)
60	        if (freed_values[i] == value)
61	            return 1;
62	    return 0;
63	}
64	
65	#define MAX_COLLECT 16
66	typedef struct {
67	    const char *keys[MAX_COLLECT];
68	    void *values[MAX_COLLECT];
69	    int n;
70	} collect_ctx_t;
71	
72	static void collect_cb(const char *key, void *value, void *ctx)
73	{
74	    collect_ctx_t *c = ctx;
75	    assert(c->n < MAX_COLLECT);
76	    c->keys[c->n] = key;
77	    c->values[c->n] = value;
78	    c->n++;
79	}
80	
81	typedef struct {
82	    const char *name;
83	    rb_value_free_fn value_free;
84	    int fail_at;          /* 0 = no injected malloc failure */
85	    int expect_nonnull;
86	    int expect_free_count; /* rb_free calls during the faulted create; -1 = n/a */
87	} create_case_t;
88	
89	/* Baseline success (with/without value_free), and injected failure on
90	 * each of rb_create's two allocations (the struct, then the nil
91	 * sentinel). Each row that returns non-NULL also exercises
92	 * destroy-after-success being crash-free and memcheck-clean, and now
93	 * checks rb_validate and that value_free is never spuriously invoked
94	 * on an empty tree.
95	 *
96	 * fail_at assumes rb_create makes exactly two rb_malloc calls, in this
97	 * order: the tree struct, then the nil sentinel. If that allocation
98	 * strategy changes, these cases will fail loudly via expect_nonnull
99	 * rather than silently no-op. expect_free_count values: fail_at=1
100	 * fails before anything is allocated, so cleanup frees nothing (0);
101	 * fail_at=2 fails after the tree struct succeeds, so cleanup frees
102	 * exactly that one allocation (1). */
103	static const create_case_t create_cases[] = {
104	    { "create_null_value_free",    NULL,          0, 1, -1 },
105	    { "create_nonnull_value_free", counting_free, 0, 1, -1 },
106	    { "create_fail_first_alloc",   NULL,          1, 0,  0 },
107	    { "create_fail_second_alloc",  NULL,          2, 0,  1 },
108	};
109	
110	static void test_rb_create(void)
111	{
112	    size_t n = sizeof create_cases / sizeof create_cases[0];
113	    /* invariant: each iteration leaves no allocation armed and no tree
114	     * leaked, regardless of whether rb_create succeeded. */
115	    for (size_t i = 0; i < n; i++) {
116	        const create_case_t *c = &create_cases[i];
117	
118	        if (c->fail_at)
119	            fault_malloc_arm(c->fail_at);
120	        rbtree_t *t = rb_create(c->value_free);
121	        if (c->fail_at) {
122	            assert(fault_malloc_free_count() == c->expect_free_count);
123	            fault_malloc_disarm();
124	        }
125	
126	        assert((t != NULL) == c->expect_nonnull);
127	
128	        if (t) {
129	            assert(rb_size(t) == 0);
130	            assert(rb_validate(t) == 0);
131	            assert(rb_find(t, "probe") == NULL);
132	            int calls = 0;
133	            rb_foreach(t, count_cb, &calls);
134	            assert(calls == 0);
135	            value_free_calls = 0;
136	            rb_destroy(t);
137	            assert(value_free_calls == 0);
138	        }
139	        printf("ok - %s\n", c->name);
140	    }
141	
142	    /* Two live trees don't share hidden state. */
143	    {
144	        rbtree_t *a = rb_create(NULL);
145	        rbtree_t *b = rb_create(NULL);
146	        assert(a && b && a != b);
147	        assert(rb_size(a) == 0 && rb_size(b) == 0);
148	        assert(rb_validate(a) == 0 && rb_validate(b) == 0);
149	        rb_destroy(a);
150	        assert(rb_size(b) == 0);
151	        rb_destroy(b);
152	        printf("ok - create_independent_instances\n");
153	    }
154	
155	    /* rb_destroy is documented NULL-safe. */
156	    {
157	        rb_destroy(NULL);
158	        printf("ok - create_destroy_null_safe\n");
159	    }
160	}
161	
162	/* White-box fixture helper: builds one node directly (bypassing rb_insert)
163	 * so test_rb_validate can wire up structurally-valid-but-invariant-violating
164	 * trees that rb_insert itself should never be able to produce. */
165	static rbnode_t *mk_node(rbtree_t *t, const char *key, int color)
166	{
167	    rbnode_t *n = rb_malloc(sizeof *n);
168	    assert(n);
169	    n->key = rb_malloc(strlen(key) + 1);
170	    assert(n->key);
171	    memcpy(n->key, key, strlen(key) + 1);
172	    n->value = NULL;
173	    n->left = n->right = n->parent = t->nil;
174	    n->color = color;
175	    return n;
176	}
177	
178	/* rb_validate must enforce four invariants: BST order, red implies black
179	 * children, equal black-height on every root-to-nil path, and the root is
180	 * black. Each case below isolates exactly one of those, and every violation
181	 * gets its left/right (or shallow/deep) mirror so an implementation that
182	 * only checks one side can't pass by accident. */
183	static void test_rb_validate(void)
184	{
185	    /* Cases 1-4: red-red violation (a red node with a red child), at each
186	     * combination of which side of the root the red parent is on and which
187	     * side of that parent the red child is on. Ordering is correct and both
188	     * root-to-nil paths carry the same black count in every case, so only
189	     * the red-red rule is broken. */
190	    {
191	        static const struct {
192	            const char *name;
193	            const char *parent_key;
194	            int parent_is_left;      /* parent is root's left (1) or right (0) child */
195	            const char *child_key;
196	            int child_is_left;       /* red child is parent's left (1) or right (0) child */
197	        } cases[] = {
198	            { "validate_red_red_LL", "d", 1, "b", 1 },
199	            { "validate_red_red_LR", "d", 1, "f", 0 },
200	            { "validate_red_red_RL", "t", 0, "r", 1 },
201	            { "validate_red_red_RR", "t", 0, "v", 0 },
202	        };
203	        for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
204	            rbtree_t *t = rb_create(NULL);
205	            assert(t);
206	
207	            rbnode_t *parent = mk_node(t, cases[i].parent_key, RB_RED);
208	            rbnode_t *child = mk_node(t, cases[i].child_key, RB_RED);
209	            child->parent = parent;
210	            if (cases[i].child_is_left)
211	                parent->left = child;
212	            else
213	                parent->right = child;
214	
215	            rbnode_t *root = mk_node(t, "m", RB_BLACK);
216	            root->parent = t->nil;
217	            if (cases[i].parent_is_left) {
218	                root->left = parent;
219	                root->right = t->nil;
220	            } else {
221	                root->right = parent;
222	                root->left = t->nil;
223	            }
224	            parent->parent = root;
225	            t->root = root;
226	            t->size = 3;
227	
228	            assert(rb_validate(t) != 0);
229	            rb_destroy(t);
230	            printf("ok - %s\n", cases[i].name);
231	        }
232	    }
233	
234	    /* Cases 5-8: BST-order violation. The first two are immediate
235	     * parent/child inversions; the last two are deeper ancestor-bound
236	     * violations -- a node that's fine relative to its immediate parent but
237	     * violates a grandparent's bound, which a validator that only compares
238	     * a node to its direct parent (instead of threading a min/max bound)
239	     * would miss. All nodes BLACK so there's no red-red/black-height noise. */
240	    {
241	        rbtree_t *t = rb_create(NULL);
242	        assert(t);
243	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
244	        rbnode_t *left = mk_node(t, "z", RB_BLACK); /* should be < "m" */
245	        root->left = left;
246	        root->right = t->nil;
247	        root->parent = t->nil;
248	        left->parent = root;
249	        t->root = root;
250	        t->size = 2;
251	        assert(rb_validate(t) != 0);
252	        rb_destroy(t);
253	        printf("ok - validate_bst_order_immediate_left_too_big\n");
254	    }
255	    {
256	        rbtree_t *t = rb_create(NULL);
257	        assert(t);
258	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
259	        rbnode_t *right = mk_node(t, "b", RB_BLACK); /* should be > "m" */
260	        root->right = right;
261	        root->left = t->nil;
262	        root->parent = t->nil;
263	        right->parent = root;
264	        t->root = root;
265	        t->size = 2;
266	        assert(rb_validate(t) != 0);
267	        rb_destroy(t);
268	        printf("ok - validate_bst_order_immediate_right_too_small\n");
269	    }
270	    {
271	        rbtree_t *t = rb_create(NULL);
272	        assert(t);
273	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
274	        rbnode_t *left = mk_node(t, "d", RB_BLACK);       /* valid: "d" < "m" */
275	        rbnode_t *deep = mk_node(t, "x", RB_BLACK);       /* valid vs "d": "x" > "d" ... */
276	        left->right = deep;                               /* ...but "x" > "m" violates root's bound */
277	        left->left = t->nil;
278	        deep->left = deep->right = t->nil;
279	        root->left = left;
280	        root->right = t->nil;
281	        root->parent = t->nil;
282	        left->parent = root;
283	        deep->parent = left;
284	        t->root = root;
285	        t->size = 3;
286	        assert(rb_validate(t) != 0);
287	        rb_destroy(t);
288	        printf("ok - validate_bst_order_deep_left_exceeds_root\n");
289	    }
290	    {
291	        rbtree_t *t = rb_create(NULL);
292	        assert(t);
293	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
294	        rbnode_t *right = mk_node(t, "t", RB_BLACK);      /* valid: "t" > "m" */
295	        rbnode_t *deep = mk_node(t, "c", RB_BLACK);       /* valid vs "t": "c" < "t" ... */
296	        right->left = deep;                                /* ...but "c" < "m" violates root's bound */
297	        right->right = t->nil;
298	        deep->left = deep->right = t->nil;
299	        root->right = right;
300	        root->left = t->nil;
301	        root->parent = t->nil;
302	        right->parent = root;
303	        deep->parent = right;
304	        t->root = root;
305	        t->size = 3;
306	        assert(rb_validate(t) != 0);
307	        rb_destroy(t);
308	        printf("ok - validate_bst_order_deep_right_below_root\n");
309	    }
310	
311	    /* Cases 9-10: black-height mismatch. All nodes BLACK, correct BST
312	     * order, differing only in which side carries an extra black node. */
313	    {
314	        rbtree_t *t = rb_create(NULL);
315	        assert(t);
316	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
317	        rbnode_t *left = mk_node(t, "b", RB_BLACK);
318	        left->left = left->right = t->nil;
319	        root->left = left;
320	        root->right = t->nil; /* one black shorter than the left path */
321	        root->parent = t->nil;
322	        left->parent = root;
323	        t->root = root;
324	        t->size = 2;
325	        assert(rb_validate(t) != 0);
326	        rb_destroy(t);
327	        printf("ok - validate_black_height_left_heavy\n");
328	    }
329	    {
330	        rbtree_t *t = rb_create(NULL);
331	        assert(t);
332	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
333	        rbnode_t *right = mk_node(t, "v", RB_BLACK);
334	        right->left = right->right = t->nil;
335	        root->right = right;
336	        root->left = t->nil; /* one black shorter than the right path */
337	        root->parent = t->nil;
338	        right->parent = root;
339	        t->root = root;
340	        t->size = 2;
341	        assert(rb_validate(t) != 0);
342	        rb_destroy(t);
343	        printf("ok - validate_black_height_right_heavy\n");
344	    }
345	
346	    /* Case 11: root color. A single red root is valid BST order (only one
347	     * node), has no red-red violation (no children to conflict with), and
348	     * has equal (zero-length) black-height on both sides -- the only broken
349	     * rule is that the root itself must be black. */
350	    {
351	        rbtree_t *t = rb_create(NULL);
352	        assert(t);
353	        rbnode_t *root = mk_node(t, "m", RB_RED);
354	        root->left = root->right = t->nil;
355	        root->parent = t->nil;
356	        t->root = root;
357	        t->size = 1;
358	        assert(rb_validate(t) != 0);
359	        rb_destroy(t);
360	        printf("ok - validate_root_must_be_black\n");
361	    }
362	}
363	
364	typedef struct {
365	    const char *name;
366	    const char *key;
367	    void *value;
368	    int fail_at;           /* 0 = no injected malloc failure */
369	    int expect_ok;         /* expect rb_insert to return 0 */
370	} insert_case_t;
371	
372	/* Cases 1-3: baseline success, and injected failure on each of
373	 * rb_insert's internal allocations. Order-agnostic about which
374	 * allocation (node struct vs. key copy) fail_at hits -- the header's
375	 * -1 contract must hold identically either way. */
376	static const insert_case_t insert_cases[] = {
377	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1 },
378	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0 },
379	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0 },
380	};
381	
382	static void test_rb_insert(void)
383	{
384	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
385	    /* invariant: each iteration gets a fresh tree, so a case's outcome
386	     * never depends on a prior case's inserts. */
387	    for (size_t i = 0; i < n; i++) {
388	        const insert_case_t *c = &insert_cases[i];
389	        rbtree_t *t = rb_create(NULL);
390	        assert(t);
391	
392	        if (c->fail_at)
393	            fault_malloc_arm(c->fail_at);
394	        int rc = rb_insert(t, c->key, c->value);
395	        if (c->fail_at)
396	            fault_malloc_disarm();
397	
398	        assert((rc == 0) == c->expect_ok);
399	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
400	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
401	
402	        rb_destroy(t);
403	        printf("ok - %s\n", c->name);
404	    }
405	
406	    /* Case 4: on allocation failure the tree must not call value_free,
407	     * and the caller must retain sole ownership of value. */
408	    {
409	        rbtree_t *t = rb_create(track_free);
410	        assert(t);
411	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
412	            reset_tracking();
413	            char *v = malloc(8);
414	            assert(v);
415	            strcpy(v, "owned");
416	
417	            fault_malloc_arm(fail_at);
418	            int rc = rb_insert(t, "delta", v);
419	            fault_malloc_disarm();
420	
421	            assert(rc == -1);
422	            assert(!was_freed(v));
423	            assert(rb_size(t) == 0);
424	            free(v);   /* caller still owns it; must not double-free */
425	        }
426	        rb_destroy(t);
427	        printf("ok - insert_failure_value_not_consumed\n");
428	    }
429	
430	    /* Case 5: overwriting an existing key frees the old value via
431	     * value_free, keeps size unchanged, and matches by key content (two
432	     * distinct buffers with identical content, not the same pointer). */
433	    {
434	        rbtree_t *t = rb_create(track_free);
435	        assert(t);
436	        reset_tracking();
437	
438	        char key_first[] = "dup";
439	        char key_second[] = "dup";
440	        char *old_value = malloc(8);
441	        char *new_value = malloc(8);
442	        assert(old_value && new_value);
443	        strcpy(old_value, "old");
444	        strcpy(new_value, "new");
445	
446	        assert(rb_insert(t, key_first, old_value) == 0);
447	        assert(rb_insert(t, key_second, new_value) == 0);
448	
449	        assert(rb_size(t) == 1);
450	        assert(was_freed(old_value));
451	        assert(!was_freed(new_value));
452	        assert(rb_find(t, "dup") == new_value);
453	
454	        /* A couple more surviving entries, so destroy has to walk multiple
455	         * nodes, not just the one left over from the overwrite. */
456	        char *extra1 = malloc(8);
457	        char *extra2 = malloc(8);
458	        assert(extra1 && extra2);
459	        strcpy(extra1, "extra1");
460	        strcpy(extra2, "extra2");
461	        assert(rb_insert(t, "extra-key-1", extra1) == 0);
462	        assert(rb_insert(t, "extra-key-2", extra2) == 0);
463	
464	        rb_destroy(t);
465	        /* rb_destroy must run value_free on every value still owned by the
466	         * tree, not just the one already freed by the earlier overwrite. */
467	        assert(was_freed(new_value));
468	        assert(was_freed(extra1));
469	        assert(was_freed(extra2));
470	        assert(freed_count == 4); /* old_value (overwrite) + 3 freed by destroy */
471	        printf("ok - insert_overwrite_frees_old_value\n");
472	    }
473	
474	    /* Case 6: distinct keys each get their own slot; size accumulates
475	     * and lookups don't cross-contaminate. Keys are inserted from mutable
476	     * buffers that get scribbled over right after each insert returns --
477	     * if rb_insert stored the caller's pointer instead of rb_malloc+memcpy
478	     * copying it, the lookups below would see the mutated content instead
479	     * of the original key. */
480	    {
481	        rbtree_t *t = rb_create(NULL);
482	        assert(t);
483	        char buf_a[] = "a-key", buf_m[] = "m-key", buf_z[] = "z-key";
484	        assert(rb_insert(t, buf_a, "a-value") == 0);
485	        assert(rb_insert(t, buf_m, "m-value") == 0);
486	        assert(rb_insert(t, buf_z, "z-value") == 0);
487	        memset(buf_a, 'X', strlen(buf_a));
488	        memset(buf_m, 'X', strlen(buf_m));
489	        memset(buf_z, 'X', strlen(buf_z));
490	
491	        assert(rb_size(t) == 3);
492	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
493	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
494	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
495	        assert(rb_find(t, "q-key") == NULL);
496	        assert(rb_find(t, "XXXXX") == NULL);
497	
498	        rb_destroy(t);
499	        printf("ok - insert_distinct_keys_prove_key_copy\n");
500	    }
501	
502	    /* Case 7: an ascending run of inserts forces left-rotations during
503	     * insert-fixup; rebalancing must preserve red-black invariants and
504	     * BST (sorted in-order) structure. */
505	    {
506	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
507	        size_t run_len = sizeof keys / sizeof keys[0];
508	        rbtree_t *t = rb_create(NULL);
509	        assert(t);
510	        /* invariant: every insert in this run succeeds before the next
511	         * begins, so size == i+1 after the i-th insert. */
512	        for (size_t i = 0; i < run_len; i++) {
513	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
514	            assert(rb_size(t) == i + 1);
515	        }
516	
517	        assert(rb_validate(t) == 0);
518	
519	        collect_ctx_t collected = {0};
520	        rb_foreach(t, collect_cb, &collected);
521	        assert(collected.n == (int)run_len);
