523	         * inserted keys are distinct. */
524	        for (int i = 0; i + 1 < collected.n; i++)
525	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
526	        /* invariant: foreach's value for each slot is exactly the pointer
527	         * that was inserted for that key (sorted order == insertion order
528	         * here, since the run was already ascending). */
529	        for (int i = 0; i < collected.n; i++)
530	            assert(collected.values[i] == (void *)keys[i]);
531	
532	        /* Every key must still be reachable by search after the rotations
533	         * this run triggered, not just present in the in-order walk. */
534	        for (size_t i = 0; i < run_len; i++)
535	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
536	
537	        rb_destroy(t);
538	        printf("ok - insert_rebalances_ascending_run\n");
539	    }
