542	     * insert-fixup; same invariants must hold. */
543	    {
544	        static const char *keys[] = { "g", "f", "e", "d", "c", "b", "a" };
545	        size_t run_len = sizeof keys / sizeof keys[0];
546	        rbtree_t *t = rb_create(NULL);
547	        assert(t);
548	        for (size_t i = 0; i < run_len; i++) {
549	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
550	            assert(rb_size(t) == i + 1);
551	        }
552	
553	        assert(rb_validate(t) == 0);
554	
555	        collect_ctx_t collected = {0};
556	        rb_foreach(t, collect_cb, &collected);
557	        assert(collected.n == (int)run_len);
558	        for (int i = 0; i + 1 < collected.n; i++)
559	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
560	        /* invariant: foreach's value for each slot is exactly the pointer
561	         * that was inserted for that key; sorted order is the reverse of
