567	         * this run triggered, not just present in the in-order walk. */
568	        for (size_t i = 0; i < run_len; i++)
569	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
570	
571	        rb_destroy(t);
572	        printf("ok - insert_rebalances_descending_run\n");
573	    }
