575	    /* Case 9: a minimal LR zig-zag. "c" becomes the black root; "a" inserts
576	     * red as its left child with the fixup loop not running (parent is the
577	     * root); "b" then inserts red as "a"'s right child. "a" is red and is
578	     * "c"'s left child while "b" is "a"'s right child -- the mismatched
579	     * shape that forces a left-rotation at "a" followed by a right-rotation
580	     * at "c" (a genuine double rotation, not two independent single ones). */
581	    {
582	        static const char *keys[] = { "c", "a", "b" };
583	        /* sorted[] references keys[]'s own elements (not fresh literals) so
584	         * the value-pointer check below compares against the exact pointer
585	         * that was inserted, not a look-alike duplicate. */
586	        const char *sorted[] = { keys[1], keys[2], keys[0] }; /* a, b, c */
587	        size_t run_len = sizeof keys / sizeof keys[0];
588	        rbtree_t *t = rb_create(NULL);
589	        assert(t);
590	        for (size_t i = 0; i < run_len; i++) {
591	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
592	            assert(rb_size(t) == i + 1);
593	        }
594	
595	        assert(rb_validate(t) == 0);
596	
597	        collect_ctx_t collected = {0};
598	        rb_foreach(t, collect_cb, &collected);
599	        assert(collected.n == (int)run_len);
