613	     * black root; "c" inserts red as its right child; "b" then inserts red
614	     * as "c"'s left child. "c" is "a"'s right child while "b" is "c"'s left
615	     * child, forcing a right-rotation at "c" then a left-rotation at "a". */
616	    {
617	        static const char *keys[] = { "a", "c", "b" };
618	        const char *sorted[] = { keys[0], keys[2], keys[1] }; /* a, b, c */
619	        size_t run_len = sizeof keys / sizeof keys[0];
620	        rbtree_t *t = rb_create(NULL);
621	        assert(t);
622	        for (size_t i = 0; i < run_len; i++) {
